  "brdf.frag.glsl": "vec4 encodeNormalizedFloatsToRGBA8(float value1, float value2) {\nfloat scaledValue1 = value1 * 65535.0;\nfloat scaledValue2 = value2 * 65535.0;\nvec4 encoded;\nencoded.r = floor(scaledValue1 / 256.0) / 255.0;                 // High byte\nencoded.g = floor(fract(scaledValue1 / 256.0) * 256.0) / 255.0;  // Low byte\nencoded.b = floor(scaledValue2 / 256.0) / 255.0;                 // High byte\nencoded.a = floor(fract(scaledValue2 / 256.0) * 256.0) / 255.0;  // Low byte\nreturn encoded;\n}\nstruct BaseColorParams {\nvec3 uniformBaseColor;\nfloat uniformOpacity;\nvec4 baseColorAtlasUvMod;\nvec4 baseColorCorrection;\nfloat cutoutMaskThreshold;\n};\nstruct BumpParams {\nvec4 bumpCorrection;\nfloat bumpOrNormalScale;\n};\nstruct ChromaKeyParams {\nvec3 keyColor;\nvec3 deltaCoeff;\n};\nstruct FogParams {\nfloat distStart;\nfloat distDensity;\nfloat heightStart;\nfloat heightDensity;\nvec3 color;\n};\nstruct HighlightParams {\nvec3 color;\nfloat mix;\n};\nstruct LightmapParams {\nvec2 size, invSize;\nvec2 threshold;\nint liveLightmapMode;\n};\nstruct LiveLightmapParams {\nvec2 screenSize;\nint mode;\n};\nstruct PostprocessParams {\nfloat cameraExposure;\nfloat cameraGamma;\nfloat colorMapIntensity;\nbool hdrOutput;\n};\nstruct SimplePbrParams {\nfloat uniformRoughness;\nfloat uniformMetallic;\nvec4 roughnessCorrection;\nvec4 metallicCorrection;\n};\nstruct OutlineMaterialParams {\nvec3 color;\nfloat thickness;\n};\nstruct SimpleShaderPassUniforms {\nvec4 vector1;\nvec4 vector2;\nivec4 ivector;\n};\nprecision highp float;\nin vec2 vUv0;\nlayout(std140) uniform SimpleShaderPassBlock {\nSimpleShaderPassUniforms uShaderPass;\n};\nconst float PI = 3.1415926;\nfloat radicalInverseVDC(int n) {\nfloat base = 2.0;\nfloat invBase = 1.0 / base;\nfloat result = 0.0;\nfloat denom;\nfor (int i = 0; i < 32; i++) {\nif (n > 0) {\ndenom = mod(float(n), base);\nresult += denom * invBase;\ninvBase = invBase / base;\nn = int(float(n) / base);\n}\n}\nreturn result;\n}\nvec2 hammersley(int i, int N) {\nreturn vec2(float(i) / float(N), radicalInverseVDC(i));\n}\nvec3 importanceSampleGGX(vec2 xi, vec3 N, float roughness) {\nfloat a = roughness * roughness;\nfloat phi = 2.0 * PI * xi.x;\nfloat cosTheta = sqrt((1.0 - xi.y) / (1.0 + (a * a - 1.0) * xi.y));\nfloat sinTheta = sqrt(1.0 - cosTheta * cosTheta);\nvec3 H = vec3(sinTheta * cos(phi), sinTheta * sin(phi), cosTheta);\nvec3 upVector = abs(N.z) < 0.999 ? vec3(0.0, 0.0, 1.0) : vec3(1.0, 0.0, 0.0);\nvec3 tangentX = normalize(cross(upVector, N));\nvec3 tangentY = cross(N, tangentX);\nreturn tangentX * H.x + tangentY * H.y + N * H.z;\n}\nfloat geometrySchlickGGX(float NdotV, float roughness) {\nfloat k = (roughness * roughness) / 2.0;\nfloat nom = NdotV;\nfloat denom = NdotV * (1.0 - k) + k;\nreturn nom / denom;\n}\nfloat geometrySmith(vec3 N, vec3 V, vec3 L, float roughness) {\nfloat NdotV = max(dot(N, V), 0.0);\nfloat NdotL = max(dot(N, L), 0.0);\nfloat ggx2 = geometrySchlickGGX(NdotV, roughness);\nfloat ggx1 = geometrySchlickGGX(NdotL, roughness);\nreturn ggx1 * ggx2;\n}\nvec2 integrateBrdf(float roughness, float NdotV) {\nvec3 V = vec3(sqrt(1.0 - NdotV * NdotV), 0.0, NdotV);\nvec3 N = vec3(0.0, 0.0, 1.0);\nfloat A = 0.0;\nfloat B = 0.0;\nint NumSamples = uShaderPass.ivector.x;\nfor (int i = 0; i < NumSamples; i++) {\nvec2 xi = hammersley(i, NumSamples);\nvec3 H = importanceSampleGGX(xi, N, roughness);\nvec3 L = 2.0 * dot(V, H) * H - V;\nfloat NdotL = clamp(L.z, 0.0, 1.0);\nfloat NdotH = clamp(H.z, 0.0, 1.0);\nfloat VdotH = clamp(dot(V, H), 0.0, 1.0);\nif (NdotL > 0.0) {\nfloat G = geometrySmith(N, V, L, roughness);\nfloat G_Vis = G * VdotH / (NdotH * NdotV);\nfloat Fc = pow(1.0 - VdotH, 5.0);\nA += (1.0 - Fc) * G_Vis;\nB += Fc * G_Vis;\n}\n}\nreturn vec2(A, B) / float(NumSamples);\n}\nvoid main() {\nvec2 brdf = integrateBrdf(vUv0.y, vUv0.x);\nfragColor = encodeNormalizedFloatsToRGBA8(brdf.x, brdf.y);\n}\n",

