  "wireframe.vert.glsl": "const float PI = 3.14159265358979;\nconst float RECIPROCAL_PI2 = 0.15915494;\nstruct SurfaceData {\nvec3 normal;\nvec3 position;\n};\nfloat saturate(in float a) {\nreturn clamp(a, 0.0, 1.0);\n}\nfloat easeOutCubic(in float x) {\nreturn 1.0 - pow(1.0 - x, 3.0);\n}\nvec3 inverseTransformDirection(in vec3 normal, in mat4 matrix) {\nreturn normalize((vec4(normal, 0.0) * matrix).xyz);\n}\nvec3 sphericalDecode(in vec2 spNormal) {\nfloat theta = (spNormal.x / 254.0 + 0.5) * PI;\nfloat phi = spNormal.y * (PI / 127.0);\nfloat sinTheta = sin(theta);\nreturn vec3(sinTheta * cos(phi), sinTheta * sin(phi), cos(theta));\n}\nvec2 sphericalEncode(in vec3 normal) {\nfloat theta = acos(clamp(normal.z, -1.0, 1.0));\nfloat phi = atan(normal.y, normal.x);\nfloat x = (theta / PI - 0.5) * 254.0;\nfloat y = phi * (127.0 / PI);\nreturn vec2(x, y);\n}\nstruct CameraUniforms {\nmat4x4 projectionMatrix;\nmat4x4 viewMatrix;\nmat4x4 viewProjectionMatrix;\nmat3x3 viewNormalMatrix;\nvec3 cameraPosition;\n};\nstruct MeshUniforms {\nmat4x4 modelMatrix;\nmat3x3 modelNormalMatrix;\nvec4 uv1Transform;\n};\nlayout(std140) uniform CameraBlock {\nCameraUniforms uCamera;\n};\nlayout(std140) uniform MeshBlock {\nMeshUniforms uObject;\n};\nstruct UvTransformParams {\nvec2 offset, scale;\nvec2 rotationCosSin;\n};\nvec2 transformUv(vec2 uv, UvTransformParams params) {\nconst vec2 fragmentCenter = vec2(0.5, 0.5);\nvec2 rotCosSin = params.rotationCosSin;\nmat2 uvRot = mat2(rotCosSin.x, -rotCosSin.y, rotCosSin.y, rotCosSin.x);\nreturn uvRot * (uv * params.scale - fragmentCenter) + fragmentCenter + params.offset;\n}\nvec2 computeUv1() {\nfloat zeroOrOne = min(uv1.x + uv1.y, 1.0);\nreturn uv1 * uObject.uv1Transform.zw + uObject.uv1Transform.xy * zeroOrOne;\n}\nmat4 getModelMatrix() {\nreturn uObject.modelMatrix;\n}\nmat4 getModelViewMatrix() {\nreturn uCamera.viewMatrix * uObject.modelMatrix;\n}\nmat4 getProjectionMatrix() {\nreturn uCamera.projectionMatrix;\n}\nvec3 getCameraPositionW() {\nreturn uCamera.cameraPosition.xyz;\n}\nvec4 transformPositionByModelViewProjectionMatrix(in vec4 localPosition) {\nreturn uCamera.viewProjectionMatrix * (uObject.modelMatrix * localPosition);\n}\nvec4 transformPositionByModelViewProjectionMatrix(in vec3 localPosition) {\nreturn transformPositionByModelViewProjectionMatrix(vec4(localPosition, 1.0));\n}\nvec3 transformPositionByModelViewMatrix(in vec3 localPosition) {\nreturn (uCamera.viewMatrix * (uObject.modelMatrix * vec4(localPosition, 1.0))).xyz;\n}\nvec3 transformNormalByModelViewMatrix(in vec3 localNormal) {\nreturn uCamera.viewNormalMatrix * (uObject.modelNormalMatrix * localNormal);\n}\nvec4 transformPositionByProjectionMatrix(in vec4 viewPosition) {\nreturn uCamera.projectionMatrix * viewPosition;\n}\nvec4 transformPositionByProjectionMatrix(in vec3 viewPosition) {\nreturn transformPositionByProjectionMatrix(vec4(viewPosition, 1.0));\n}\nvec3 transformPositionByModelMatrix(in vec3 position) {\nreturn (uObject.modelMatrix * vec4(position, 1.0)).xyz;\n}\nvec3 transformNormalByModelMatrix(in vec3 direction) {\nreturn uObject.modelNormalMatrix * direction;\n}\nstruct Vertex {\nvec3 position;\nvec3 normal;\n};\nVertex localVertex(vec3 inputPosition, vec2 inputSphericalNormal) {\nVertex v;\nv.position = inputPosition;\nv.normal = sphericalDecode(inputSphericalNormal);\nreturn v;\n}\nVertex viewVertex(Vertex localVertex) {\nVertex v;\nv.position = transformPositionByModelViewMatrix(localVertex.position);\nv.normal = normalize(transformNormalByModelViewMatrix(localVertex.normal));\nreturn v;\n}\nVertex worldVertex(Vertex localVertex) {\nVertex v;\nv.position = transformPositionByModelMatrix(localVertex.position);\nv.normal = normalize(transformNormalByModelMatrix(localVertex.normal));\nreturn v;\n}\nout vec3 vBarycentric;\nout vec3 vPositionV;\nvoid main() {\nint order = gl_VertexID % 3;\nif (order == 0)\nvBarycentric = vec3(1.0, 0.0, 0.0);\nelse if (order == 1)\nvBarycentric = vec3(0.0, 1.0, 0.0);\nelse\nvBarycentric = vec3(0.0, 0.0, 1.0);\nvec3 localPosition = position;\nvec3 viewPosition = transformPositionByModelViewMatrix(localPosition);\nvPositionV = -viewPosition;\ngl_Position = transformPositionByProjectionMatrix(viewPosition);\n}\n"
